insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NL:registered-nurse','2026-08-11',null,null,37536,20,0,0,0,8,6,0,3,1,38,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2221 Nursing Professionals; Dutch Verpleegkundige scope.','shortage_note','UWV identifies general and specialised nurses as structurally promising and reports continuing severe healthcare shortages in 2026; 20/20.','visa_basis','There is no nurse-specific Dutch migration fast track. Non-EU work remains dependent on the applicable IND route, employer and permit conditions; 3/10.','salary_method','Studiekeuze123 HBO Verpleegkunde estimated graduate starting salary EUR 3,128/month, annualised to EUR 37,536; a transparent early-career proxy rather than an occupation-wide median; 6/10.','entry_basis','Recognised mbo-4 or hbo nursing education plus BIG registration is required; the hbo route is commonly four years; 8/15.','entry_burden_basis','Verpleegkundige is an Article 3 Wet BIG profession and mandatory BIG registration applies; 1/5.'),'2026-08-11'),
('NL:midwife','2026-08-11',null,null,43788,15,0,0,0,6,8,0,3,1,33,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2222 Midwifery Professionals; Dutch Verloskundige scope.','shortage_note','Healthcare remains structurally tight, but the current reviewed UWV evidence is less occupation-specific for midwives than for nurses, physiotherapists and verzorgenden; 15/20.','visa_basis','BIG recognition does not create an occupation-specific IND migration fast track; employer and permit rules still apply; 3/10.','salary_method','Studiekeuze123 Verloskunde estimated graduate starting salary EUR 3,649/month, annualised to EUR 43,788; 8/10.','entry_basis','Direct four-year hbo bachelor Verloskunde followed by BIG registration; 6/15.','entry_burden_basis','Verloskundige is an Article 3 Wet BIG profession and mandatory BIG registration applies; 1/5.'),'2026-08-11'),
('NL:care-worker','2026-08-11',null,21.00,43680,20,0,0,0,15,8,0,3,3,49,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 5321 Health Care Assistants; canonical scope constrained to Dutch Verzorgende IG / hands-on care work.','shortage_note','UWV identifies verzorgenden as a major shortage group and Verzorgende IG as structurally promising; KiesMBO reports the strongest current job-prospect score; 20/20.','visa_basis','There is no care-worker-specific Dutch migration fast track. Non-EU employment remains route-, employer- and permit-dependent; 3/10.','salary_method','KiesMBO Verzorgende IG BOL starting pay EUR 21/hour annualised at 2,080 hours to EUR 43,680; 8/10.','entry_basis','Direct MBO level 3 Verzorgende IG route, normally two to three years with BOL/BBL options; 15/15.','entry_burden_basis','Verzorgende IG is an Article 34 protected education title but not an Article 3 BIG-register profession; 3/5.'),'2026-08-11'),
('NL:physiotherapist','2026-08-11',null,null,33024,20,0,0,0,8,4,0,3,1,36,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2264 Physiotherapists; Dutch Fysiotherapeut scope.','shortage_note','UWV explicitly lists physiotherapists among occupations with major shortages in Q1 2026 and expects pressure to rise toward 2030; 20/20.','visa_basis','No physiotherapist-specific Dutch migration fast track; Highly Skilled Migrant access remains sponsor- and salary-dependent; 3/10.','salary_method','Studiekeuze123 Fysiotherapie estimated graduate starting salary EUR 2,752/month, annualised to EUR 33,024; 4/10.','entry_basis','Four-year hbo physiotherapy degree followed by BIG registration; 8/15.','entry_burden_basis','Fysiotherapeut is an Article 3 Wet BIG profession and mandatory BIG registration applies; 1/5.'),'2026-08-11'),
('NL:medical-lab-tech','2026-08-11',null,19.00,39520,15,0,0,0,12,6,0,3,5,41,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 3212 Medical and Pathology Laboratory Technicians; Dutch Biologisch Medisch Analist technician scope.','shortage_note','UWV continues to identify laboratory and biochemistry work as promising, while KiesMBO reports good current job prospects for Biologisch Medisch Analist; 15/20.','visa_basis','No medical-laboratory-technician-specific Dutch migration fast track; 3/10.','salary_method','KiesMBO Biologisch Medisch Analist starting pay EUR 19/hour annualised at 2,080 hours to EUR 39,520; 6/10.','entry_basis','Direct MBO level 4 Biologisch Medisch Analist route, normally three to four years; 12/15.','entry_burden_basis','No universal Article 3 BIG registration applies to the canonical biomedical laboratory technician scope; 5/5.'),'2026-08-11'),
('NL:radiographer','2026-08-11',null,null,37428,15,0,0,0,8,6,0,3,3,35,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 3211 Medical Imaging and Therapeutic Equipment Technicians; Dutch Radiodiagnostisch laborant / MBRT imaging scope.','shortage_note','UWV identifies paramedical care as a promising higher-education healthcare segment; current evidence is supportive but less occupation-specific than for nurses or physiotherapists; 15/20.','visa_basis','No radiographer-specific Dutch migration fast track; standard IND work/residence conditions apply; 3/10.','salary_method','Studiekeuze123 MBRT estimated graduate starting salary EUR 3,119/month, annualised to EUR 37,428; 6/10.','entry_basis','Direct hbo bachelor Medisch Beeldvormende en Radiotherapeutische Technieken; 8/15.','entry_burden_basis','Radiodiagnostisch laborant is an Article 34 protected education title, not an Article 3 BIG-register profession; 3/5.'),'2026-08-11'),
('NL:pharmacist','2026-08-11',null,null,40524,10,0,0,0,6,8,0,3,1,28,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2262 Pharmacists; Dutch Apotheker scope.','shortage_note','Healthcare remains structurally tight and Pharmacy graduate outcomes are very good, but the reviewed current UWV evidence is not sufficiently pharmacist-specific for maximum shortage credit; 10/20.','visa_basis','Pharmacist status does not itself create an IND fast track. Highly Skilled Migrant access requires a recognised sponsor and the applicable salary criterion; 3/10.','salary_method','Studiekeuze123 Farmacie estimated graduate starting salary EUR 3,377/month, annualised to EUR 40,524; 8/10.','entry_basis','University Pharmacy bachelor-plus-master route is a long professional pathway before BIG registration; 6/15.','entry_burden_basis','Apotheker is an Article 3 Wet BIG profession and mandatory BIG registration applies; 1/5.'),'2026-08-11'),
('NL:occupational-therapist','2026-08-11',null,null,35940,15,0,0,0,8,6,0,3,3,35,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2269 Health Professionals Not Elsewhere Classified; Dutch Ergotherapeut scope.','shortage_note','UWV identifies paramedical healthcare as a promising segment; Studiekeuze123 shows strong study-to-field and study-to-level matching for Ergotherapie graduates; 15/20.','visa_basis','No occupational-therapist-specific Dutch migration fast track; 3/10.','salary_method','Studiekeuze123 Ergotherapie estimated graduate starting salary EUR 2,995/month, annualised to EUR 35,940; 6/10.','entry_basis','Direct four-year hbo Ergotherapie route; 8/15.','entry_burden_basis','Ergotherapeut is an Article 34 protected education title but not an Article 3 BIG-register profession; 3/5.'),'2026-08-11')
